-- 5 kategori ve 10 Türkçe örnek makale. Tekrar çalıştırıldığında aynı başlıkları eklemez.
SET NOCOUNT ON;
SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;
SET ANSI_PADDING ON;
SET ANSI_WARNINGS ON;
SET ARITHABORT ON;
SET CONCAT_NULL_YIELDS_NULL ON;
SET NUMERIC_ROUNDABORT OFF;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
IF NOT EXISTS (SELECT 1 FROM Categories WHERE CategoryName=N'Teknoloji') INSERT INTO Categories (CategoryName) VALUES (N'Teknoloji');
IF NOT EXISTS (SELECT 1 FROM Categories WHERE CategoryName=N'Spor') INSERT INTO Categories (CategoryName) VALUES (N'Spor');
IF NOT EXISTS (SELECT 1 FROM Categories WHERE CategoryName=N'Yemek') INSERT INTO Categories (CategoryName) VALUES (N'Yemek');
IF NOT EXISTS (SELECT 1 FROM Categories WHERE CategoryName=N'Seyahat') INSERT INTO Categories (CategoryName) VALUES (N'Seyahat');
IF NOT EXISTS (SELECT 1 FROM Categories WHERE CategoryName=N'Kültür Sanat') INSERT INTO Categories (CategoryName) VALUES (N'Kültür Sanat');
IF NOT EXISTS (SELECT 1 FROM Articles WHERE Title=N'Yapay Zekâ ile Çalışırken Daha İyi Sorular Sormak')
INSERT INTO Articles (Title,CoverImageUrl,MainImageUrl,Content,CreatedDate,CategoryId,IsFeatureSlider,FeatureSliderImageUrl,AppUserId)
SELECT N'Yapay Zekâ ile Çalışırken Daha İyi Sorular Sormak',N'/images/LLM1.jpg',N'/images/LLM1.jpg',N'Yapay zekâ araçlarından yararlı bir yanıt almak için önce görevi açıkça tanımlamak gerekir. Örneğin bir metin özeti isterken hedef kitleyi, beklenen uzunluğu ve korunması gereken bilgileri belirtmek çıktının değerlendirilmesini kolaylaştırır. Büyük işleri küçük adımlara ayırmak ve her adımın sonucunu incelemek de faydalıdır. Üretilen metinlerdeki iddiaları kaynaklarla kontrol edin; kişisel veya gizli bilgileri paylaşmadan önce kullandığınız hizmetin veri koşullarını inceleyin. Son kararı kendi değerlendirmenizle verin.',DATEADD(hour,-10,CONVERT(datetime2,'2026-10-11T16:00:00',126)),(SELECT MIN(CategoryId) FROM Categories WHERE CategoryName=N'Teknoloji'),1,N'/images/LLM1.jpg',NULL;
IF NOT EXISTS (SELECT 1 FROM Articles WHERE Title=N'Bir Web Projesinde API ve Veritabanı Nasıl Birlikte Çalışır?')
INSERT INTO Articles (Title,CoverImageUrl,MainImageUrl,Content,CreatedDate,CategoryId,IsFeatureSlider,FeatureSliderImageUrl,AppUserId)
SELECT N'Bir Web Projesinde API ve Veritabanı Nasıl Birlikte Çalışır?',N'/images/team-developer.jpg',N'/images/team-developer.jpg',N'Bir web uygulamasında arayüz kullanıcının isteğini API’ye gönderir. API, isteğin alanlarını doğrular ve gerekli verileri veritabanından alarak yanıt oluşturur. Kategoriye göre makale listelemek bu akışın basit bir örneğidir: kategori kimliği gönderilir, ilgili kayıtlar sorgulanır ve sonuç arayüzde gösterilir. Veritabanı bağlantı bilgilerini kaynak koddan ayrı tutmak, sorguları parametrelerle çalıştırmak ve hataları anlaşılır şekilde kaydetmek bakım sürecini kolaylaştırır. Docker ise geliştirme ortamındaki veritabanını ayrı bir servis olarak çalıştırmaya yardımcı olur.',DATEADD(hour,-9,CONVERT(datetime2,'2026-10-11T16:00:00',126)),(SELECT MIN(CategoryId) FROM Categories WHERE CategoryName=N'Teknoloji'),0,N'/images/team-developer.jpg',NULL;
IF NOT EXISTS (SELECT 1 FROM Articles WHERE Title=N'Bir Spor Günlüğünde Hangi Bilgiler Tutulabilir?')
INSERT INTO Articles (Title,CoverImageUrl,MainImageUrl,Content,CreatedDate,CategoryId,IsFeatureSlider,FeatureSliderImageUrl,AppUserId)
SELECT N'Bir Spor Günlüğünde Hangi Bilgiler Tutulabilir?',N'/images/lifestyle.jpg',N'/images/lifestyle.jpg',N'Spor günlüğü, yaptığınız etkinlikleri düzenli biçimde kaydetmek için kullanılabilir. Tarih, etkinlik türü, süre ve kişisel gözlemler temel alanlardır. Bir yürüyüşten sonra izlenen rota ve hava koşulları; bir takım antrenmanından sonra çalışılan beceriler not edilebilir. Kayıtları başka kişilerin performansıyla karşılaştırmak yerine kendi deneyiminizi anlamak için kullanın. Haftalık bir değerlendirmede hangi etkinliklerden keyif aldığınızı ve planınızı hangi koşulların etkilediğini gözden geçirebilirsiniz. Bu günlük kişisel bir kayıt aracıdır; tıbbi değerlendirme yerine geçmez.',DATEADD(hour,-8,CONVERT(datetime2,'2026-10-11T16:00:00',126)),(SELECT MIN(CategoryId) FROM Categories WHERE CategoryName=N'Spor'),1,N'/images/lifestyle.jpg',NULL;
IF NOT EXISTS (SELECT 1 FROM Articles WHERE Title=N'Takım Sporlarında İletişimin Rolü')
INSERT INTO Articles (Title,CoverImageUrl,MainImageUrl,Content,CreatedDate,CategoryId,IsFeatureSlider,FeatureSliderImageUrl,AppUserId)
SELECT N'Takım Sporlarında İletişimin Rolü',N'/images/team-developer2.jpg',N'/images/team-developer2.jpg',N'Takım sporlarında ortak hareket etmek, herkesin görevini ve takım arkadaşlarının beklentilerini anlamasıyla kolaylaşır. Antrenman öncesinde hedefi konuşmak ve saha içinde kısa, anlaşılır ifadeler kullanmak koordinasyonu destekler. Bir pozisyonu değerlendirirken kişiyi suçlamak yerine olayın nasıl geliştiğini ve bir sonraki denemede neyin değiştirilebileceğini konuşmak daha somut bir yaklaşım sağlar. Takım toplantılarında farklı görüşlere yer vermek de ortak kararları görünür kılar. İletişim yalnızca konuşmak değildir; takım arkadaşını dinlemek ve verilen bilgiyi doğru zamanda paylaşmak da bu sürecin parçasıdır.',DATEADD(hour,-7,CONVERT(datetime2,'2026-10-11T16:00:00',126)),(SELECT MIN(CategoryId) FROM Categories WHERE CategoryName=N'Spor'),0,N'/images/team-developer2.jpg',NULL;
IF NOT EXISTS (SELECT 1 FROM Articles WHERE Title=N'Mevsim Sebzeleriyle Fırın Tepsisi Hazırlamak')
INSERT INTO Articles (Title,CoverImageUrl,MainImageUrl,Content,CreatedDate,CategoryId,IsFeatureSlider,FeatureSliderImageUrl,AppUserId)
SELECT N'Mevsim Sebzeleriyle Fırın Tepsisi Hazırlamak',N'/articleimages/04.jpg',N'/articleimages/04.jpg',N'Fırın sebze tepsisi, elinizdeki sebzeleri tek bir yemekte değerlendirmek için pratik bir seçenektir. Sebzeleri yıkayıp benzer büyüklükte doğrayın; daha geç pişen parçaları küçük tutun. Bir kapta zeytinyağı ve tercih ettiğiniz baharatlarla karıştırıp tepsiye tek kat halinde yayın. Önceden ısıtılmış yaklaşık 200 derecelik fırında pişirin ve ara sıra kontrol edin. Pişme süresi sebzenin türüne, parça büyüklüğüne ve fırına göre değişir; sebzeler yumuşayıp kenarları renk aldığında tepsiyi çıkarabilirsiniz. Dilerseniz yoğurt veya limonlu bir sosla servis edin.',DATEADD(hour,-6,CONVERT(datetime2,'2026-10-11T16:00:00',126)),(SELECT MIN(CategoryId) FROM Categories WHERE CategoryName=N'Yemek'),1,N'/articleimages/04.jpg',NULL;
IF NOT EXISTS (SELECT 1 FROM Articles WHERE Title=N'Haftalık Yemek Planını Kolaylaştıran Bir Alışveriş Listesi')
INSERT INTO Articles (Title,CoverImageUrl,MainImageUrl,Content,CreatedDate,CategoryId,IsFeatureSlider,FeatureSliderImageUrl,AppUserId)
SELECT N'Haftalık Yemek Planını Kolaylaştıran Bir Alışveriş Listesi',N'/articleimages/05.jpg',N'/articleimages/05.jpg',N'Haftalık yemek planına başlamadan önce dolapta ve buzdolabında bulunan malzemeleri gözden geçirin. Ardından hazırlamak istediğiniz yemekleri seçip eksikleri sebze, bakliyat, süt ürünleri ve diğer malzemeler gibi gruplara ayırın. Aynı malzemeyi birkaç yemekte değerlendirmek alışveriş listesini sadeleştirebilir. Planınıza hazırlık için ayırabileceğiniz zamanı da ekleyin; yoğun günler için daha az işlem gerektiren yemekler seçebilirsiniz. Ambalajdaki saklama ve tüketim talimatlarını dikkate alın. Haftanın sonunda kullanılmayan malzemeleri not ederek bir sonraki alışverişin miktarını yeniden düzenleyin.',DATEADD(hour,-5,CONVERT(datetime2,'2026-10-11T16:00:00',126)),(SELECT MIN(CategoryId) FROM Categories WHERE CategoryName=N'Yemek'),0,N'/articleimages/05.jpg',NULL;
IF NOT EXISTS (SELECT 1 FROM Articles WHERE Title=N'Şehir Gezisi İçin Esnek Bir Rota Hazırlamak')
INSERT INTO Articles (Title,CoverImageUrl,MainImageUrl,Content,CreatedDate,CategoryId,IsFeatureSlider,FeatureSliderImageUrl,AppUserId)
SELECT N'Şehir Gezisi İçin Esnek Bir Rota Hazırlamak',N'/images/travel1.jpeg',N'/images/travel1.jpeg',N'Bir şehir gezisinde her saati doldurmak yerine birbirine yakın birkaç durağı aynı güne yerleştirmek planı daha yönetilebilir kılar. Önce görmek istediğiniz yerleri haritada işaretleyin ve yürüyüş mesafelerini inceleyin. Açılış saatlerini ve rezervasyon koşullarını geziden önce ilgili kurumların resmi sayfalarından kontrol edin. Ulaşım, yemek ve dinlenme için boş zaman bırakın. Yağmur veya beklenmedik bir kapanış için alternatif bir durak belirlemek de işe yarar. Planı kesin bir program olarak değil, günün koşullarına göre güncelleyebileceğiniz bir rehber olarak kullanın.',DATEADD(hour,-4,CONVERT(datetime2,'2026-10-11T16:00:00',126)),(SELECT MIN(CategoryId) FROM Categories WHERE CategoryName=N'Seyahat'),1,N'/images/travel1.jpeg',NULL;
IF NOT EXISTS (SELECT 1 FROM Articles WHERE Title=N'Seyahat Fotoğraflarında Bir Hikâye Kurmak')
INSERT INTO Articles (Title,CoverImageUrl,MainImageUrl,Content,CreatedDate,CategoryId,IsFeatureSlider,FeatureSliderImageUrl,AppUserId)
SELECT N'Seyahat Fotoğraflarında Bir Hikâye Kurmak',N'/images/roma.jpg',N'/images/roma.jpg',N'Seyahat fotoğrafları yalnızca ünlü yapıları kaydetmekle sınırlı değildir. Bir sokağın genel görünümü, küçük bir mimari ayrıntı ve günün atmosferini gösteren bir kare birlikte bir hikâye oluşturabilir. Aynı yeri farklı açılardan gözlemlemek, ışığın yüzeylerdeki etkisini fark etmeyi sağlar. Fotoğraf çekerken geçiş yollarını kapatmamaya ve mekânın kurallarına uymaya özen gösterin. İnsanların yakın plan görüntülerini çekerken izin isteyin. Gün sonunda fotoğraflarınıza konum ve kısa notlar eklemek, daha sonra o anın bağlamını hatırlamanızı kolaylaştırır.',DATEADD(hour,-3,CONVERT(datetime2,'2026-10-11T16:00:00',126)),(SELECT MIN(CategoryId) FROM Categories WHERE CategoryName=N'Seyahat'),0,N'/images/roma.jpg',NULL;
IF NOT EXISTS (SELECT 1 FROM Articles WHERE Title=N'Bir Sergiyi Gezerken Kendi Notlarınızı Oluşturmak')
INSERT INTO Articles (Title,CoverImageUrl,MainImageUrl,Content,CreatedDate,CategoryId,IsFeatureSlider,FeatureSliderImageUrl,AppUserId)
SELECT N'Bir Sergiyi Gezerken Kendi Notlarınızı Oluşturmak',N'/images/festival1.jpg',N'/images/festival1.jpg',N'Bir sergiyi gezerken ilk izlenimlerinizi kısa notlarla kaydetmek eserlerle kurduğunuz ilişkiyi daha görünür hale getirebilir. Eserin adı, sanatçısı, malzemesi ve sizde uyandırdığı sorular başlangıç için yeterlidir. Önce eseri gözlemleyip ardından açıklama metnini okumak, kendi yorumunuz ile sunulan bağlamı karşılaştırmanıza yardımcı olur. Her eseri uzun uzun incelemek zorunda değilsiniz; dikkatinizi çeken birkaç çalışma üzerinde durabilirsiniz. Fotoğraf çekmeden önce salonun kurallarını kontrol edin. Ziyaret sonrası notlarınızdan küçük bir değerlendirme yazısı hazırlayabilirsiniz.',DATEADD(hour,-2,CONVERT(datetime2,'2026-10-11T16:00:00',126)),(SELECT MIN(CategoryId) FROM Categories WHERE CategoryName=N'Kültür Sanat'),1,N'/images/festival1.jpg',NULL;
IF NOT EXISTS (SELECT 1 FROM Articles WHERE Title=N'Okuma Günlüğüyle Kitapları Hatırlamak')
INSERT INTO Articles (Title,CoverImageUrl,MainImageUrl,Content,CreatedDate,CategoryId,IsFeatureSlider,FeatureSliderImageUrl,AppUserId)
SELECT N'Okuma Günlüğüyle Kitapları Hatırlamak',N'/images/festival2.jpg',N'/images/festival2.jpg',N'Okuma günlüğü, bitirdiğiniz kitapların ana düşüncelerini ve kişisel izlenimlerinizi saklamak için basit bir yöntemdir. Kitabın adı, yazarı ve okuma tarihiyle başlayıp birkaç cümlelik bir değerlendirme ekleyin. Bir romanda karakterlerin kararlarını, bir denemede yazarın temel sorusunu not edebilirsiniz. Alıntı kaydediyorsanız sayfa numarasını da yazın ve alıntıyla kendi yorumunuzu ayırın. Uzun bir inceleme hazırlamak şart değildir; merak ettiğiniz noktalar ve başka kitaplarla kurduğunuz bağlantılar da değerlidir. Zaman içinde bu kayıtlar kişisel bir okuma haritası oluşturur.',DATEADD(hour,-1,CONVERT(datetime2,'2026-10-11T16:00:00',126)),(SELECT MIN(CategoryId) FROM Categories WHERE CategoryName=N'Kültür Sanat'),0,N'/images/festival2.jpg',NULL;
