VALUES (N'seed-author-deniz-yilmaz',N'Deniz',N'Yılmaz',N'Teknoloji Editörü',N'Yapay zekâ ve web geliştirme konularında anlaşılır rehberler hazırlayan örnek yazar profili.',N'/images/authors/deniz-yilmaz.svg',N'seed.deniz-yilmaz',N'SEED.DENIZ-YILMAZ',0,NULL,CONVERT(nvarchar(36),NEWID()),CONVERT(nvarchar(36),NEWID()),0,0,1,0);
